#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    int even = n / 2;
    int odd = n - even;

    vector<int> a(n);
    for (int& x : a) {
        cin >> x;
        if (x == 0) continue;

        if (x % 2 == 0) {
            --even;
        } else {
            --odd;
        }
    }

    int orig_complexity = 0;
    for (int i = 0; i + 1 < n; ++i) {
        if (a[i] == 0 || a[i + 1] == 0) continue;
        if (a[i] % 2 != a[i + 1] % 2) ++orig_complexity;
    }

    int dissim_p_cnt = 0;
    vector<pair<int, int>> similar_s;

    int i = 0;
    while (i < n) {
        if (a[i] != 0) {
            ++i;
            continue;
        }

        int left_idx = i - 1;
        while (i < n && a[i] == 0) ++i;
        int right_idx = i;

        if (right_idx == n || left_idx == -1 ||
            a[right_idx] % 2 == a[left_idx] % 2) {
            int seglen = right_idx - left_idx - 1;
            int parity = left_idx != -1
                ? a[left_idx] % 2
                : (right_idx != n ? a[right_idx] % 2 : 1);
            similar_s.push_back({seglen, parity});
        } else {
            ++dissim_p_cnt;
        }
    }

    sort(similar_s.begin(), similar_s.end());

    int similar_failed = 0;
    for (const auto& [len, parity] : similar_s) {
        int& capacity = parity == 0 ? even : odd;
        if (capacity >= len) {
            capacity -= len;
        } else {
            ++similar_failed;
        }
    }

    cout << orig_complexity + dissim_p_cnt + similar_failed * 2;
    return 0;
}

