#include <iostream>
#include <vector>
#include <array>
#include <algorithm>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    vector<int> a(n);
    for (int& x : a) cin >> x;

    const int evenCount = n / 2;
    const int oddCount = n - evenCount;
    const int INF = 1e9;

    vector<array<int, 2>> dp(evenCount + 1), next(evenCount + 1);
    for (auto& x : dp) x = {INF, INF};
    dp[0] = {0, 0};

    for (int i = 0; i < n; ++i) {
        for (auto& x : next) x = {INF, INF};

        for (int usedEven = 0; usedEven <= evenCount; ++usedEven) {
            for (int lastParity = 0; lastParity < 2; ++lastParity) {
                if (dp[usedEven][lastParity] == INF) continue;

                for (int parity = 0; parity < 2; ++parity) {
                    if (a[i] != 0 && a[i] % 2 != parity) continue;

                    int newUsedEven = usedEven + (parity == 0);
                    int usedOdd = i + 1 - newUsedEven;

                    if (newUsedEven > evenCount || usedOdd > oddCount) continue;

                    int cost = dp[usedEven][lastParity];
                    if (i > 0 && lastParity != parity) ++cost;

                    next[newUsedEven][parity] =
                        min(next[newUsedEven][parity], cost);
                }
            }
        }

        dp.swap(next);
    }

    cout << min(dp[evenCount][0], dp[evenCount][1]);
    return 0;
}

